import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import type { Post, Comment } from '@/types/blog'

export const dynamicParams = true
export const revalidate = 300

interface BlogPostPageProps {
  params: Promise<{ id: string }>
}

export async function generateStaticParams() {
  try {
    const posts: Post[] = await fetch(
      'https://jsonplaceholder.typicode.com/posts'
    ).then((res) => res.json())

    return posts.slice(0, 10).map((post) => ({
      id: post.id.toString(),
    }))
  } catch {
    return []
  }
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  try {
    const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
      next: { revalidate: 300 },
    })
    if (!res.ok) {
      return {}
    }
    const post: Post = await res.json()
    if (!post || !post.title) {
      return {}
    }
    const description = post.body ? post.body.substring(0, 160) : ''
    return {
      title: `${post.title} - My Blog`,
      description,
      openGraph: {
        title: post.title,
        description,
      },
    }
  } catch {
    return {}
  }
}

async function getPostAndComments(id: string) {
  try {
    const [postRes, commentsRes] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 },
      }),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }),
    ])

    if (!postRes.ok || !commentsRes.ok) {
      notFound()
    }

    const post: Post = await postRes.json()
    const comments: Comment[] = await commentsRes.json()

    if (!post || !post.id || !post.title) {
      notFound()
    }

    return { post, comments }
  } catch {
    notFound()
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const { post, comments } = await getPostAndComments(id)

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

