import { NextResponse } from 'next/server'

export interface SinglePostItem {
  id: number
  title: string
  content: string
  createdAt: string
}

export interface UpdatedPostItem {
  id: number
  title: string
  content: string
  updatedAt: string
}

interface RouteContext {
  params: Promise<{ id: string }>
}

export async function GET(
  _request: Request,
  context: RouteContext
) {
  const { id } = await context.params

  // Simulate fetching a single post
  const post: SinglePostItem = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post, { status: 200 })
}

export async function PUT(
  request: Request,
  context: RouteContext
) {
  const { id } = await context.params

  try {
    const body = await request.json()
    const { title, content } = body

    // Simulate updating a post
    const updatedPost: UpdatedPostItem = {
      id: parseInt(id, 10),
      title: title || `Post ${id}`,
      content: content || `Updated content for post ${id}`,
      updatedAt: new Date().toISOString(),
    }

    return NextResponse.json(updatedPost, { status: 200 })
  } catch {
    const updatedPost: UpdatedPostItem = {
      id: parseInt(id, 10),
      title: `Post ${id}`,
      content: `Updated content for post ${id}`,
      updatedAt: new Date().toISOString(),
    }

    return NextResponse.json(updatedPost, { status: 200 })
  }
}

export async function DELETE(
  _request: Request,
  context: RouteContext
) {
  const { id } = await context.params

  // Simulate deleting a post
  return NextResponse.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  )
}

